            // (word & alpha) & ~prev(word)
            let w = r_m_word[q % RING] & r_m_alpha[q % RING] & (!(r_m_word[q % RING] << 1 | r_m_word[(q + RING - 1) % RING] >> 63) & lv & lv);
            r_t44[q % RING] = w;
